 const addBrick=()=>{if(!Object.values(coords).every(Number.isInteger)||coords.y<0||Object.values(coords).some(n=>Math.abs(n)>128))return toast.error('Use whole coordinates between -128 and 128, with Y ≥ 0.');const brick:Brick={id:crypto.randomUUID(),part:addPart,color:addColor,...coords,rot:addRot};const next=[...model.bricks,brick];if(checks(next).overlaps>geometry.overlaps)return toast.error('This position overlaps another brick.');commit({...model,bricks:next});setSelected(brick.id);setModal('');toast.success('Brick added.');};
